import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {memo} from 'react'
import {useNavigate} from 'react-router'

import {getAddRepositoryHref} from '../../../../../../routes'
import {usePipelineId} from '../../../hooks/pipeline'
import usePermissionCanEditPipeline from '../../../hooks/usePermissionCanEditPipeline'
import type {VcsProviderType} from '../../../services/pipelinesApi.types'
import {isWithoutVcsFeatureEnabled} from '../../../utils/featureToggles'
import {addRepositoryNoPermissionsMessage} from '../../RepositoryRequiredDialog/RepositoryRequiredDialog.consts'
import VcsProviderIcon from '../../VcsProviderIcon/VcsProviderIcon'

import RepositoryTag from './RepositoryTag/RepositoryTag'

import styles from './RepositoryBadge.module.css'

import Badge from 'src/components/common/Badge/Badge'
import MiddleEllipsis from 'src/components/common/MiddleEllipsis/MiddleEllipsis'

type Props = {
  className?: string
  displayedRepo?: string
  additionalRepos?: string[]
  vcsProviderType?: VcsProviderType | null
  isLoading?: boolean
}
function RepositoryBadge({
  className,
  displayedRepo,
  additionalRepos,
  isLoading,
  vcsProviderType,
}: Props) {
  const pipelineId = usePipelineId()
  const navigate = useNavigate()
  const {canEditPipeline} = usePermissionCanEditPipeline()
  const hasVcsRoot = displayedRepo != null
  const tooltipMessage = !canEditPipeline ? addRepositoryNoPermissionsMessage : undefined

  if (!hasVcsRoot && !isWithoutVcsFeatureEnabled) {
    return null
  }

  if (!hasVcsRoot) {
    return (
      <Badge className={classNames(styles.container, className)}>
        <div className={styles.emptyWrapper}>
          <div className={styles.label}>{'Repository'}</div>
          <div className={styles.emptyTitle}>{'No repository found'}</div>
          <Tooltip title={tooltipMessage}>
            <IconButton
              inline
              className={styles.addButton}
              icon={'add-12px'}
              disabled={!canEditPipeline}
              onClick={() => navigate(getAddRepositoryHref(pipelineId))}
            >
              {'Add'}
            </IconButton>
          </Tooltip>
        </div>
      </Badge>
    )
  }

  return (
    <Badge className={classNames(styles.container, className)} label={'Repository'}>
      <div className={classNames(styles.repository, {[styles.loading]: isLoading})}>
        <Tooltip className={styles.tooltipWrapper} title={displayedRepo} selfOverflowOnly>
          <VcsProviderIcon className={styles.icon} vcsProviderType={vcsProviderType} />
          <MiddleEllipsis className={styles.name} title={null} tailLength={10}>
            {displayedRepo}
          </MiddleEllipsis>
        </Tooltip>
        {!!additionalRepos?.length && <RepositoryTag repositories={additionalRepos} />}
      </div>
    </Badge>
  )
}

export default memo(RepositoryBadge)
