import {memo} from 'react'

import type {BuildTypeId} from '../../../../../../types'

import type {CommonProps} from './SystemProblemsBadge'
import SystemProblemsBadge from './SystemProblemsBadge'
import {useBuildTypeSystemProblemsBadge} from './SystemProblemsBadge.hooks'

type BuildTypeBadgeProps = CommonProps & {
  buildTypeId: BuildTypeId
}

function BuildTypeSystemProblemsBadge({buildTypeId, ...restProps}: BuildTypeBadgeProps) {
  const {projectId, systemProblems, additionalProblems} =
    useBuildTypeSystemProblemsBadge(buildTypeId)

  if (projectId == null) {
    return null
  }

  return (
    <SystemProblemsBadge
      {...restProps}
      projectId={projectId}
      systemProblems={systemProblems}
      additionalProblems={additionalProblems}
    />
  )
}
export default memo(BuildTypeSystemProblemsBadge)
