import {memo} from 'react'

import type {pipelineHeadBuildTypeFragment$key} from '../../../hooks/__generated__/pipelineHeadBuildTypeFragment.graphql'

import type {CommonProps} from './SystemProblemsBadge'
import SystemProblemsBadge from './SystemProblemsBadge'
import {usePipelineSystemProblemsBadge} from './SystemProblemsBadge.hooks'

type PipelineBadgeProps = CommonProps & {
  pipelineHeadBuildTypeKey: pipelineHeadBuildTypeFragment$key | null
}

function PipelineSystemProblemsBadge({pipelineHeadBuildTypeKey, ...restProps}: PipelineBadgeProps) {
  const {projectId, systemProblems, additionalProblems} =
    usePipelineSystemProblemsBadge(pipelineHeadBuildTypeKey)

  if (projectId == null) {
    return null
  }

  return (
    <SystemProblemsBadge
      {...restProps}
      projectId={projectId}
      systemProblems={systemProblems}
      additionalProblems={additionalProblems}
    />
  )
}

export default memo(PipelineSystemProblemsBadge)
