import Button from '@jetbrains/ring-ui-built/components/button/button'
import Dialog from '@jetbrains/ring-ui-built/components/dialog/dialog'
import {H2} from '@jetbrains/ring-ui-built/components/heading/heading'
import {Content} from '@jetbrains/ring-ui-built/components/island/island'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import {resolveRelative} from '@jetbrains/teamcity-ui/dist/utils'
import type {ReactNode} from 'react'
import * as React from 'react'
import {Suspense} from 'react'

import {useDerivedState} from '../../../hocs/withDerivedState'
import {usePermission} from '../../../hooks/usePermission'
import type {ProjectId, SystemProblem} from '../../../types'
import {Permission, stringifyId} from '../../../types'
import Details from '../Details/Details'
import {useParentVisibility} from '../Visible/Visible.hooks'

import styles from './SystemProblemsDialog.module.css'

type StacktraceProps = {text: string}
function Stacktrace({text}: StacktraceProps) {
  const [isOpen, toggle] = React.useReducer(state => !state, false)
  return (
    <Details
      headingClassName={styles.stacktraceHeading}
      open={isOpen}
      onToggle={toggle}
      label="Stacktrace"
      summary={
        <>
          <SvgIcon
            className={styles.chevronIcon}
            title={isOpen ? 'Hide' : 'Show'}
            icon={isOpen ? 'chevron-down' : 'chevron-right'}
          />
          {'Stacktrace'}
        </>
      }
    >
      <pre className={styles.stacktrace}>{text}</pre>
    </Details>
  )
}

type SolveProps = {
  projectId?: ProjectId | null
  isInternalError: boolean
  href: string
  children: ReactNode
}
function Solve({projectId, isInternalError, href, children}: SolveProps) {
  const canEdit = usePermission(Permission.EDIT_PROJECT, projectId)

  return (
    (isInternalError || canEdit) && (
      <Button className={styles.solutionLink} inline href={href}>
        {children}
      </Button>
    )
  )
}

type Props = {
  projectId?: ProjectId
  systemProblems?: ReadonlyArray<SystemProblem>
  additionalProblems?: ReadonlyArray<SystemProblem>
  isOpenDialog: boolean
  closeDialog: () => void
}

function SystemProblemsDialog({
  projectId,
  systemProblems = [],
  additionalProblems = [],
  isOpenDialog,
  closeDialog,
}: Props) {
  const isVisible = useParentVisibility()
  const wasVisible = useDerivedState(false, state => state || isVisible === true)

  return (
    <Dialog
      className={styles.dialog}
      contentClassName={styles.dialogContent}
      label="System Problems"
      showCloseButton
      closeButtonInside
      show={isOpenDialog}
      onCloseAttempt={closeDialog}
    >
      <Content className={styles.content}>
        <div>
          {[...systemProblems, ...additionalProblems].map(
            ({id, webSpecifics, type, description, problemDetails}) => (
              <div key={stringifyId(id)} className={styles.item}>
                {webSpecifics != null && (
                  <div className={styles.itemHeadingWrapper}>
                    <H2 className={styles.heading}>{webSpecifics.caption}</H2>
                    {wasVisible && (
                      <Suspense>
                        <Solve
                          projectId={projectId}
                          isInternalError={type === 'INTERNAL_ERROR'}
                          href={resolveRelative(webSpecifics.solutionLink.link)}
                        >
                          {webSpecifics.solutionLink.title ?? 'Solve the problem'}
                        </Solve>
                      </Suspense>
                    )}
                  </div>
                )}
                <div className={styles.description}>{description}</div>
                {problemDetails != null && <Stacktrace text={problemDetails} />}
              </div>
            ),
          )}
        </div>
      </Content>
    </Dialog>
  )
}

export default SystemProblemsDialog
