import {useAppSelector} from '../../../../../../hooks/react-redux'
import {useBranch} from '../../../../../../hooks/routes'
import useStatusSubscription from '../../../../../../hooks/useStatusSubscription'
import {getBuildType, getStatus} from '../../../../../../selectors'
import type {BuildTypeId} from '../../../../../../types'
import {getBuildTypeStatusRequest, getPipelineStatusRequest} from '../../../../../../types'
import type {pipelineHeadBuildTypeFragment$key} from '../../../hooks/__generated__/pipelineHeadBuildTypeFragment.graphql'
import {usePipelineHead, usePipelineId} from '../../../hooks/pipeline'

export const usePipelineSystemProblemsBadge = (
  pipelineHeadBuildTypeKey: pipelineHeadBuildTypeFragment$key | null,
) => {
  const pipelineId = usePipelineId()
  const branch = useBranch()
  useStatusSubscription({pipelineId})

  const projectId = usePipelineHead(pipelineHeadBuildTypeKey)?.projectId
  const status = useAppSelector(state =>
    getStatus(state, getPipelineStatusRequest(pipelineId, branch)),
  )
  return {
    projectId,
    systemProblems: status?.systemProblems,
    additionalProblems: status?.additionalProblems,
  }
}

export const useBuildTypeSystemProblemsBadge = (buildTypeId: BuildTypeId) => {
  const branch = useBranch()
  useStatusSubscription({buildTypeId})

  const projectId = useAppSelector(state => getBuildType(state, buildTypeId)?.projectId)
  const status = useAppSelector(state =>
    getStatus(state, getBuildTypeStatusRequest(buildTypeId, branch)),
  )
  return {
    projectId,
    systemProblems: status?.systemProblems,
    additionalProblems: status?.additionalProblems,
  }
}
