import {useEffect, useState} from 'react'

type BranchSelectLoadEvent = {
  shouldBeVisible: boolean
  defaultBranchVcsName?: string | null | undefined
}

function useBranchBadge(branchName?: string, headId?: string | null) {
  const [isShowBranchSelect, setIsShowBranchSelect] = useState<boolean>(headId != null)
  const [branch, setBranch] = useState<string | undefined>(branchName)

  useEffect(() => {
    setIsShowBranchSelect(headId != null)
  }, [headId])

  const branchSelectLoadHandler = ({
    shouldBeVisible,
    defaultBranchVcsName,
  }: BranchSelectLoadEvent) => {
    if (!shouldBeVisible && defaultBranchVcsName) {
      setBranch(defaultBranchVcsName)
      setIsShowBranchSelect(false)
    } else if (!shouldBeVisible) {
      setIsShowBranchSelect(false)
    }
  }
  const isDisplay = Boolean(branch || (headId && isShowBranchSelect))

  return {
    branch,
    isDisplay,
    isShowBranchSelect,
    branchSelectLoadHandler,
  }
}

export default useBranchBadge
