import classNames from 'classnames'
import {memo, Suspense} from 'react'
import type {PreloadedQuery} from 'react-relay/relay-hooks/EntryPointTypes'

import BranchSelect from '../../../../../../containers/BranchFilter'
import {Policy} from '../../../../../../rest/branches'
import type {BranchSelectBranchesQuery} from '../../../../../common/BranchSelect/__generated__/BranchSelectBranchesQuery.graphql'
import Tooltip from '../../Tooltip/Tooltip'

import useBranchBadge from './useBranchBadge'

import styles from './BranchBadge.module.css'

import Badge from 'src/components/common/Badge/Badge'
import BranchLabel from 'src/components/common/BranchLabel/BranchLabel'

type Props = {
  className?: string
  branchName?: string
  headId?: string | null
  branchesQueryRef?: PreloadedQuery<BranchSelectBranchesQuery> | null
}
function BranchBadge({className, branchName, headId, branchesQueryRef}: Props) {
  const {branch, isDisplay, isShowBranchSelect, branchSelectLoadHandler} = useBranchBadge(
    branchName,
    headId,
  )

  if (!isDisplay) {
    return null
  }

  return (
    <Badge className={classNames(styles.container, className)} label={'Branch'}>
      {isShowBranchSelect ? (
        branchesQueryRef && (
          <Suspense>
            <BranchSelect
              className={styles.branchSelectButton}
              projectOrBuildTypeNode={{nodeType: 'bt', headId}}
              policy={Policy.ALL_BRANCHES}
              branchesQueryRef={branchesQueryRef}
              onLoad={branchSelectLoadHandler}
              inline
              withTooltip
            />
          </Suspense>
        )
      ) : (
        <Tooltip className={styles.wrapper} title={branch} selfOverflowOnly>
          <BranchLabel
            nameClassName={styles.branchName}
            name={branch}
            title={null}
            tailLength={10}
            withIcon
            noLink
            inline
          />
        </Tooltip>
      )}
    </Badge>
  )
}

export default memo(BranchBadge)
