import classNames from 'classnames'

import type {ChipStatusProps} from './ChipStatus.types'

import styles from './ChipStatus.module.css'

function ChipStatus({status, children}: ChipStatusProps) {
  const chipStatusClassNames = classNames(styles.status, styles[status])

  return <span className={chipStatusClassNames}>{children}</span>
}

export default ChipStatus
