import classNames from 'classnames'
import {memo} from 'react'

import {capitalizeFirstLetter} from '../../../utils/string'
import Tooltip from '../../Tooltip/Tooltip'

import styles from './TriggeredByBadge.module.css'

import Avatar, {Size} from 'src/components/common/Avatar/Avatar.container'
import Badge from 'src/components/common/Badge/Badge'
import type {NormalizedBuildTriggered} from 'src/types'
import {useDisplayDate} from 'src/utils/dateTimeUtils'

type Props = {
  className?: string
  triggered?: NormalizedBuildTriggered
}
function TriggeredByBadge({className, triggered}: Props) {
  const triggeredDate = useDisplayDate(triggered?.date, true)
  const triggeredBy =
    triggered?.displayText != null ? capitalizeFirstLetter(triggered.displayText) : 'Unknown'
  const text = `${triggeredBy} at ${triggeredDate}`
  const hasAvatar = triggered?.user != null

  return (
    <Badge className={classNames(styles.container, className)} label={'Triggered by'}>
      <Tooltip
        className={classNames(styles.wrapper, {[styles.noAvatar]: !hasAvatar})}
        title={text}
        selfOverflowOnly
      >
        {hasAvatar && <Avatar user={triggered.user} size={Size.Size20} />}
        {text}
      </Tooltip>
    </Badge>
  )
}

export default memo(TriggeredByBadge)
