import Button from '@jetbrains/ring-ui-built/components/button/button'
import Tag from '@jetbrains/ring-ui-built/components/tag/tag'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'

import type {ProjectId, SystemProblem} from '../../../../../../types'
import {useSequenceLoaderReadyHandler} from '../../../../../common/SequenceLoader/SequenceLoader.hooks'
import type {SeqProps} from '../../../../../common/SequenceLoader/SequenceLoader.types'
import SystemProblemsDialog from '../../../../../common/SystemProblemsDialog/SystemProblemsDialog'
import useBooleanState from '../../../hooks/useBooleanState'
import Tooltip from '../../Tooltip/Tooltip'

import styles from './SystemProblemsBadge.module.css'

import Badge from 'src/components/common/Badge/Badge'

export type CommonProps = {
  className?: string
} & SeqProps

type Props = CommonProps & {
  projectId: ProjectId
  systemProblems?: SystemProblem[]
  additionalProblems?: SystemProblem[]
}

function SystemProblemsBadge({
  className,
  projectId,
  systemProblems = [],
  additionalProblems = [],
}: Props) {
  const [isOpenDialog, openDialog, closeDialog] = useBooleanState(false)
  useSequenceLoaderReadyHandler(true)

  if (!systemProblems?.length) {
    return null
  }

  const message = systemProblems[0].title
  const count = systemProblems.length + additionalProblems.length - 1

  return (
    <>
      <Badge className={classNames(styles.container, className)}>
        <div className={styles.header}>
          <div className={styles.label}>{'Error'}</div>
          <Button className={styles.showMore} onClick={openDialog} inline>
            {'Show more'}
          </Button>
        </div>
        <div className={styles.error}>
          <SvgIcon className={styles.icon} icon="warning" />
          <Tooltip className={styles.tooltipWrapper} title={message}>
            <div className={styles.message}>{message}</div>
          </Tooltip>
          {Boolean(count) && (
            <div className={styles.tagWrapper} title="Show more">
              <Tag className={styles.tag} onClick={openDialog} readOnly>{`+${count}`}</Tag>
            </div>
          )}
        </div>
      </Badge>
      <SystemProblemsDialog
        projectId={projectId}
        systemProblems={systemProblems}
        additionalProblems={additionalProblems}
        isOpenDialog={isOpenDialog}
        closeDialog={closeDialog}
      />
    </>
  )
}

export default SystemProblemsBadge
