import RingIcon from '@jetbrains/ring-ui-built/components/icon/icon'
import classNames from 'classnames'

import GitIcon from '../../../../common/GitIcon/GitIcon'
import type {VcsProviderType} from '../../services/pipelinesApi.types'

import {VcsProviderIconMap} from './VcsProviderIcon.consts'

import styles from './VcsProviderIcon.module.css'

type Props = {
  vcsProviderType?: VcsProviderType | null
  className?: string
}

function VcsProviderIcon({className, vcsProviderType}: Props) {
  const Icon = vcsProviderType ? VcsProviderIconMap[vcsProviderType] : GitIcon
  const providerTypeIconClassName = vcsProviderType
    ? styles[`${vcsProviderType.toLowerCase()}` as keyof typeof styles]
    : null

  if (Icon == null) {
    return null
  }

  return <RingIcon className={classNames(className, providerTypeIconClassName)} glyph={Icon} />
}

export default VcsProviderIcon
