import {memo} from 'react'

import {useAppSelector} from '../../../../../../hooks/react-redux'
import {getBuildAgent} from '../../../../../../selectors'
import {restApi} from '../../../../../../services/rest'
import {BuildStatusType} from '../../../../../../types'
import {AgentBadge as BaseAgentBadge} from '../../../../../common/Badges'
import {
  usePipelineRunArg,
  usePipelineRunJobAgentCompatibilityStatus,
} from '../../../PipelineRunPage/PipelineRunPage.hooks'

import AgentBadgeAgentIncompatibilityReasons from './AgentBadgeAgentIncompatibilityReasons'

type Props = {
  className?: string
  runId?: number
}
function AgentBadge({className, runId}: Props) {
  const agent = useAppSelector(state => (runId != null ? getBuildAgent(state, runId) : null))
  const arg = usePipelineRunArg()
  const {runBuild} = restApi.endpoints.getBuildNormalized.useQuery(arg, {
    selectFromResult: ({data}) => {
      const run = data?.entities?.builds?.[data?.result!]
      const runBuild = run?.['snapshot-dependencies']?.build?.find(build => build.id === runId)

      return {
        runBuild,
      }
    },
  })
  const isJobQueued = runBuild?.state === BuildStatusType.QUEUED
  const {isCurrentJobIncompatibilityAgent, pipelineSettingJobId, compatibilityAgentQueuedJob} =
    usePipelineRunJobAgentCompatibilityStatus(runBuild)

  const isShowNoCompatibleAgent = isCurrentJobIncompatibilityAgent && isJobQueued
  const isShowAgentInfo = agent != null && agent.name !== 'N/A' && runId

  if (!isShowNoCompatibleAgent && !isShowAgentInfo) {
    return null
  }

  return (
    <BaseAgentBadge
      className={className}
      buildId={runId}
      isShowNoCompatibleAgent={isShowNoCompatibleAgent}
      incompatibilityReasons={
        <AgentBadgeAgentIncompatibilityReasons
          jobId={pipelineSettingJobId}
          incompatibilityAgents={compatibilityAgentQueuedJob}
        />
      }
    />
  )
}

export default memo(AgentBadge)
